%[text] # photometric attitude estimation using UKF on Lie group (quaternion) not yet
%[text] UKFでlight curve attitude estimation
%[text] ## state variables
%[text] ${\\bf x}=\[{\\bf q}^T, {\\bf \\omega}^T\]^T$
%[text] `q`: quaternion where q(4) is the scalar part 
%[text] `w`: angular rate, rad/s
%[text] ## note
%[text] NA
%[text] ## references 
%[text] NA
%[text] ## revisions
%[text] 20240831  y.yoshimura, y.yoshimula@gmail.com
%[text] See also orbitConst, mainATOM.
clc
clear
cls
%[text] ## constants
earthVSOP = vsopConst; % VSOP parameters
const = orbitConst; % constants for orbital motion
%%
%[text] ## simulation conditions
% true value calculated by mainAttiOrbit.mlx
fName = "flatPlate"; %[control:dropdown:587a]{"position":[9,20]}
load(strcat(fName,'.mat'));

% random number generator
rng(2022,'twister');
%[text] ## observations and noise
tn_ = length(t_);

sigMapp = 0.1; %[control:editfield:1a70]{"position":[11,14]}
mAppNoise = mApp + sigMapp .* randn(tn_, 1);

% observations
dTmp = vecnorm(obsRel, 2, 2); % m, distance between sat and observer
mAppInv = magInv(mAppNoise(:,1), dTmp); % true obs. (relative magnitude inverse)
%[text] ## UKF paras.
n_ = 4; % # of state variable := quaternion
nP_ = 3;
%[text] ### UKF parameters
ukfPara.alpha = 1e-4; %[control:editfield:6806]{"position":[17,21]}
ukfPara.beta = 2; %[control:editfield:91b5]{"position":[16,17]}
ukfPara.kappa = 0; %[control:editfield:7c42]{"position":[17,18]}
ukfPara.lambda = 0.6; %[control:editfield:09e0]{"position":[18,21]}
ukfPara = setUKFpara(n_, ukfPara); %[output:5e936a9d]

% ↓ paperの
% nz = 3;
% ukfPara.lambda = 1 * nz * (ukfPara.alpha^2 - 1);
% ukfPara.w0c = ukfPara.lambda / (nz+ukfPara.lambda) + nz - ukfPara.alpha^2;
% ukfPara.wic = 1 / 2 / (nz + ukfPara.lambda);
% ukfPara.w0m = ukfPara.lambda / (nz + ukfPara.lambda);
% ukfPara.wim = 1 / 2 / (nz + ukfPara.lambda);
ukfPara %[output:1cf89b14]

% estimated observation noise (standard deviation)
Rest = (3 * sigMapp).^2;
Qest = 0 * deg2rad(1e-2)^2 .* eye(nP_); % process noise

%%
%[text] ### pre-allocation
xEst = zeros(tn_, n_); % [euler angles, angular rates]
p = zeros(tn_, nP_); % diagonal components of covariance matrix (Pcov)

%%
%[text] ## initial estiamte and covariance
xEst(1,:) = q(1,:);  % true initial
tmp = zyx2q(4, deg2rad(-20), ... %[control:editfield:98a6]{"position":[24,27]}
    deg2rad(50), ... %[control:editfield:660c]{"position":[13,15]}
    deg2rad(30)); % initial estimate error of quaternion %[control:editfield:46b0]{"position":[13,15]}
xEst(1,:) = qMult(4, 1, tmp, q(1,:));

%[text] #### initial covariance for 3$\\sigma\n$bound 
p(1,:) = deg2rad(150)^2 .* ones(1,3);
% p(1,:) = 2.618^2 .* ones(1,3);
Pcov = diag(p(1,:));

global nWindow ind adapNoise Qest Rest %[output:885d3b8c] %[output:196d1a26]
ind = 1;
nWindow = 6;
%%
%[text] ## UKF
for i = 1:tn_-1 %[output:group:631a9dc0]
    dt_ = t_(i+1) - t_(i);

    if i > nWindow
        adapNoise = 1;
    else
        adapNoise = 0;
    end

    [xEst(i+1,:), Pcov] = lcUKFonLieGroup(jdHistory(i+1), dt_, xEst(i,:), Pcov, mAppNoise(i+1), ... %[output:69ee0ad3]
        ukfPara,  w(i,:), r(i+1,:), obsECI(i+1,:), sat, const, earthVSOP); %[output:69ee0ad3]

end %[output:group:631a9dc0]

%%
%[text] ## data handling
qe = qErr(4, q, xEst);
zyxE = q2zyx(4, qe);
phiE = zyxE(:,1);
thetaE = zyxE(:,2);
psiE = zyxE(:,3);

%[text] ## show figures
figure %[output:0651cf63]
tiledlayout(4,1),nexttile %[output:0651cf63]
plot(t_, qe(:,1), 'r') %[output:0651cf63]
title('error quaternion') %[output:0651cf63]
nexttile %[output:0651cf63]
plot(t_, qe(:,2), 'g') %[output:0651cf63]
nexttile %[output:0651cf63]
plot(t_, qe(:,3), 'b') %[output:0651cf63]
nexttile %[output:0651cf63]
plot(t_, qe(:,4), 'k') %[output:0651cf63]

figure %[output:7252dc5d]
tiledlayout(3,1),nexttile %[output:7252dc5d]
plot(t_/60, rad2deg(phiE), 'r') %[output:7252dc5d]
title('Euler angle error [deg]') %[output:7252dc5d]
xlim([0 60*6]),ylim([-60 60]) %[output:7252dc5d]
nexttile %[output:7252dc5d]
plot(t_/60, rad2deg(thetaE), 'g') %[output:7252dc5d]
xlim([0 60*6]),ylim([-60 60]) %[output:7252dc5d]
nexttile %[output:7252dc5d]
plot(t_/60, rad2deg(psiE), 'b') %[output:7252dc5d]
xlim([0 60*6]),ylim([-60 60]) %[output:7252dc5d]


